import{_ as n,o as t,c as e,a6 as i}from"./chunks/framework.DycQjAfF.js";const r="/WareHouse/images/perusahaan/logo-bpi.jpg",d="/WareHouse/images/perusahaan/produksi-pipa.jpg",s="/WareHouse/images/perusahaan/industri-energi.jpg",l="/WareHouse/images/perusahaan/pemeriksaan-pipa.jpg",P=JSON.parse('{"title":"Profil Perusahaan","description":"Kenalan dengan PT Bakrie Pipe Industries, mulai dari sejarah, produk, mutu, sampai nilai kerjanya.","frontmatter":{"title":"Profil Perusahaan","description":"Kenalan dengan PT Bakrie Pipe Industries, mulai dari sejarah, produk, mutu, sampai nilai kerjanya.","status":"terverifikasi","diperbarui":"2026-10-16T00:00:00.000Z","kategori":"Tentang Perusahaan","kata_kunci":["Bakrie Pipe Industries","BPI","SEAPI","profil perusahaan","pipa baja","ERW","HFW","LSAW","HSAW","Bakrie & Brothers","Bekasi","Talang Tirta","PRIDE","nilai perusahaan"]},"headers":[],"relativePath":"perusahaan/index.md","filePath":"perusahaan/index.md"}'),p={name:"perusahaan/index.md"};function u(g,a,o,k,m,b){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="profil-perusahaan" tabindex="-1">Profil Perusahaan <a class="header-anchor" href="#profil-perusahaan" aria-label="Permalink to &quot;Profil Perusahaan&quot;">​</a></h1><p class="lead">Kenalan dulu dengan tempat kamu magang: PT Bakrie Pipe Industries, atau biasa disingkat BPI.</p><p>PT Bakrie Pipe Industries adalah produsen pipa baja las dengan pengalaman lebih dari enam dekade. BPI dikenal karena ragam produknya yang luas, pilihan ukuran yang lengkap, serta layanan proses lanjutan seperti pelapisan dan galvanisasi untuk berbagai kebutuhan infrastruktur.</p><figure><p><img src="'+r+'" alt="Lima orang berbaju batik berbincang dan tertawa di depan dinding hitam bertuliskan logo Bakrie Pipe Industries"></p><figcaption>Suasana di depan dinding logo PT Bakrie Pipe Industries.</figcaption></figure><table class="tabel-tumpuk tanpa-kepala" tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Nama perusahaan</strong></td><td>PT Bakrie Pipe Industries (BPI)</td></tr><tr><td><strong>Berawal sejak</strong></td><td>1959, dengan nama pabrik Talang Tirta</td></tr><tr><td><strong>Bidang usaha</strong></td><td>Manufaktur pipa baja las dan layanan pendukungnya</td></tr><tr><td><strong>Pabrik</strong></td><td>Bekasi, Jawa Barat</td></tr><tr><td><strong>Anak usaha</strong></td><td>PT Southeast Asia Pipe Industries (SEAPI), Lampung</td></tr><tr><td><strong>Kantor komersial</strong></td><td>Bakrie Tower, Rasuna Epicentrum, Jakarta Selatan</td></tr><tr><td><strong>Kapasitas pipa ERW</strong></td><td>310.000 MT per tahun</td></tr><tr><td><strong>Rentang diameter</strong></td><td>½ sampai 140 inci (gabungan BPI dan SEAPI)</td></tr></tbody></table><h2 id="sejarah-singkat" tabindex="-1">Sejarah singkat <a class="header-anchor" href="#sejarah-singkat" aria-label="Permalink to &quot;Sejarah singkat&quot;">​</a></h2><p>Perjalanan perusahaan dimulai dari pabrik pipa baja bernama <strong>Talang Tirta</strong>, yang didirikan oleh almarhum H. Achmad Bakrie pada 1959 di Jakarta. Pabrik kemudian pindah dan berkembang di Bekasi, lalu memakai nama PT Bakrie Pipe Industries sejak 1981.</p><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Tahun</th><th>Tonggak penting</th></tr></thead><tbody><tr><td data-label="Tahun">1959</td><td data-label="Tonggak penting">PT Bakrie &amp; Brothers mendirikan pabrik pipa baja Talang Tirta di Jakarta, dengan ukuran pipa sekitar ½ sampai 6 inci.</td></tr><tr><td data-label="Tahun">1972–⁠1978</td><td data-label="Tonggak penting">Kapasitas meningkat dan produk bertambah: pipa conduit, pipa air, pipa kotak, serta pipa minyak dan gas.</td></tr><tr><td data-label="Tahun">1979–⁠1981</td><td data-label="Tonggak penting">Nama perusahaan berubah bertahap, dan pada 1981 resmi menjadi PT Bakrie Pipe Industries dengan pabrik di Bekasi.</td></tr><tr><td data-label="Tahun">1984–⁠2008</td><td data-label="Tonggak penting">Pengembangan lisensi dan produk API, sertifikasi sistem mutu ISO 9001 pada 1992, serta peningkatan kemampuan ketebalan dinding pipa.</td></tr><tr><td data-label="Tahun">1996</td><td data-label="Tonggak penting">BPI mendirikan anak usaha PT Southeast Asia Pipe Industries (SEAPI) di Lampung untuk memproduksi pipa berdiameter besar dengan metode LSAW.</td></tr><tr><td data-label="Tahun">2013–⁠2022</td><td data-label="Tonggak penting">Perluasan fasilitas coating, pemasangan lini HSAW, pengembangan cement lining dan belled-end pipe, serta penghargaan SNI Award.</td></tr><tr><td data-label="Tahun">2023–⁠2025</td><td data-label="Tonggak penting">Penghargaan suplai tiang baja, kerja sama panel surya atap, pembangunan jetty di SEAPI, penghargaan CSR dan PROPER, serta kemampuan HSAW hingga 140 inci.</td></tr></tbody></table><p>Saat ini kegiatan perusahaan terbagi di tiga tempat:</p><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Lokasi</th><th>Peran</th></tr></thead><tbody><tr><td data-label="Lokasi">BPI, Bekasi</td><td data-label="Peran">Pabrik utama pipa HFW/ERW dan layanan pendukung manufaktur. Gudang Teknik ada di sini.</td></tr><tr><td data-label="Lokasi">SEAPI, Lampung</td><td data-label="Peran">Lini pipa LSAW dan HSAW, termasuk pipa HSAW hingga 140 inci, dilengkapi jetty untuk distribusi.</td></tr><tr><td data-label="Lokasi">Kantor komersial, Jakarta Selatan</td><td data-label="Peran">Kontak komersial dan koordinasi dengan pelanggan.</td></tr></tbody></table><h2 id="produk-dan-cara-pembuatannya" tabindex="-1">Produk dan cara pembuatannya <a class="header-anchor" href="#produk-dan-cara-pembuatannya" aria-label="Permalink to &quot;Produk dan cara pembuatannya&quot;">​</a></h2><p>BPI dan SEAPI membuat pipa baja las dengan tiga metode pengelasan. Metode yang dipakai bergantung pada diameter, ketebalan, panjang, dan spesifikasi pipa yang dibutuhkan proyek.</p><figure><p><img src="'+d+'" alt="Pekerja berhelm dan berpelindung wajah memotong ujung pipa baja hingga memercikkan bunga api di area produksi"></p><figcaption>Pemotongan pipa baja di area produksi, dengan APD lengkap: helm, pelindung wajah, dan sarung tangan.</figcaption></figure><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Metode</th><th>Penjelasan singkat</th><th>Diameter luar</th><th>Tebal dinding</th><th>Panjang</th></tr></thead><tbody><tr><td data-label="Metode"><strong>HFW / ERW</strong></td><td data-label="Penjelasan singkat">Lini utama BPI untuk pipa umum, struktur, dan energi.</td><td data-label="Diameter luar">½–24 inci</td><td data-label="Tebal dinding">1,3–17,5 mm</td><td data-label="Panjang">6–12 m</td></tr><tr><td data-label="Metode"><strong>LSAW</strong></td><td data-label="Penjelasan singkat">Pipa las memanjang, untuk pipa berdinding tebal dan proyek berspesifikasi tinggi.</td><td data-label="Diameter luar">24–48 inci</td><td data-label="Tebal dinding">7,9–34,0 mm</td><td data-label="Panjang">6–12 m</td></tr><tr><td data-label="Metode"><strong>HSAW</strong></td><td data-label="Penjelasan singkat">Pipa las spiral, untuk diameter sangat besar.</td><td data-label="Diameter luar">16–140 inci</td><td data-label="Tebal dinding">6,0–25,0 mm</td><td data-label="Panjang">6–60 m</td></tr></tbody></table><details class="details custom-block"><summary>Istilah: pipa ERW, LSAW, HSAW, dan coating</summary><p><strong>Pipa baja ERW</strong> (<em>Electric Resistance Welding</em>) atau <strong>HFW</strong> (<em>High-Frequency Welding</em>) dibuat dari lembaran baja yang digulung menjadi tabung. Kedua tepinya dipanaskan dengan arus listrik lalu ditekan sampai menyatu, tanpa kawat las tambahan.</p><p><strong>LSAW</strong> (<em>Longitudinal Submerged Arc Welding</em>) dan <strong>HSAW</strong> (<em>Helical Submerged Arc Welding</em>) memakai las busur yang terendam fluks. Pada LSAW, sambungan lasnya lurus memanjang. Pada HSAW, sambungannya melingkar seperti spiral.</p><p><strong>Coating</strong> adalah lapisan pelindung di permukaan pipa supaya tidak mudah berkarat.</p></details><p>Pipa-pipa ini dibuat mengikuti standar nasional dan internasional, misalnya API 5L dan API 5CT untuk minyak dan gas, AWWA C200 dan ASTM A53 untuk air, ASTM A252 dan SNI 8052 untuk tiang pancang dan struktur, serta standar SNI lainnya.</p><h3 id="siapa-yang-memakai-pipa-bpi" tabindex="-1">Siapa yang memakai pipa BPI? <a class="header-anchor" href="#siapa-yang-memakai-pipa-bpi" aria-label="Permalink to &quot;Siapa yang memakai pipa BPI?&quot;">​</a></h3><p>Produk BPI dipakai di banyak sektor: <strong>minyak dan gas</strong>, <strong>petrokimia</strong>, <strong>distribusi air dan proteksi kebakaran</strong>, <strong>tiang pancang dan struktur</strong> (termasuk pipa kotak RHS/SHS), <strong>kelistrikan dan telekomunikasi</strong> (tiang listrik, tiang telepon, tiang penerangan jalan), serta <strong>panas bumi</strong>.</p><figure><p><img src="'+s+'" alt="Fasilitas industri dengan menara, cerobong, dan jaringan pipa di bawah langit biru"></p><figcaption>Fasilitas industri minyak, gas, dan petrokimia seperti ini termasuk sektor pengguna pipa baja.</figcaption></figure><h3 id="layanan-pendukung" tabindex="-1">Layanan pendukung <a class="header-anchor" href="#layanan-pendukung" aria-label="Permalink to &quot;Layanan pendukung&quot;">​</a></h3><p>Selain membuat pipa, perusahaan juga menyediakan proses lanjutan:</p><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Layanan</th><th>Fungsi</th></tr></thead><tbody><tr><td data-label="Layanan">Coating eksternal dan internal</td><td data-label="Fungsi">Lapisan pelindung seperti FBE, 3LPE, dan 3LPP agar pipa lebih awet.</td></tr><tr><td data-label="Layanan">Galvanisasi</td><td data-label="Fungsi">Pelapisan seng supaya pipa lebih tahan karat.</td></tr><tr><td data-label="Layanan">Internal cement lining</td><td data-label="Fungsi">Pelapisan semen di bagian dalam pipa.</td></tr><tr><td data-label="Layanan">Slitting</td><td data-label="Fungsi">Memotong coil baja menjadi lebar tertentu sebelum dibentuk menjadi pipa.</td></tr><tr><td data-label="Layanan">Fabrikasi pendukung</td><td data-label="Fungsi">Belled-end pipe, sleeve, serta tiang listrik, telepon, dan penerangan jalan.</td></tr></tbody></table><h2 id="mutu-dan-keselamatan-kerja" tabindex="-1">Mutu dan keselamatan kerja <a class="header-anchor" href="#mutu-dan-keselamatan-kerja" aria-label="Permalink to &quot;Mutu dan keselamatan kerja&quot;">​</a></h2><p>Perusahaan menerapkan sistem manajemen mutu <strong>ISO 9001:2015</strong>, lingkungan <strong>ISO 14001:2015</strong>, serta keselamatan dan kesehatan kerja <strong>ISO 45001:2018</strong> dan <strong>SMK3</strong> dari Kementerian Ketenagakerjaan. Laboratoriumnya terakreditasi <strong>ISO/IEC 17025:2017</strong> oleh KAN.</p><p>Untuk produk, perusahaan memegang monogram <strong>API 5L, API 5CT, dan API 2B</strong>, sertifikasi <strong>SNI</strong>, <strong>SPLN</strong> dari PLN, dan <strong>STEL</strong> Telkom Indonesia.</p><p>Setiap pipa melewati berbagai pengujian, antara lain uji tarik dan uji pipih, uji hidrostatik (tekanan air), uji ultrasonik dan radiografi untuk memeriksa sambungan las, serta pengujian daya lekat dan ketahanan coating.</p><figure><p><img src="'+l+'" alt="Beberapa orang berhelm keselamatan memeriksa tumpukan pipa baja sambil membawa dokumen di area penyimpanan pabrik"></p><figcaption>Pemeriksaan tumpukan pipa baja di area penyimpanan pabrik BPI.</figcaption></figure><h2 id="nilai-kerja-pride" tabindex="-1">Nilai kerja: PRIDE <a class="header-anchor" href="#nilai-kerja-pride" aria-label="Permalink to &quot;Nilai kerja: PRIDE&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Nilai</th><th>Artinya</th></tr></thead><tbody><tr><td data-label="Nilai"><strong>Passion</strong></td><td data-label="Artinya">Bekerja dengan komitmen dan semangat untuk menghasilkan mutu terbaik.</td></tr><tr><td data-label="Nilai"><strong>Respect</strong></td><td data-label="Artinya">Menghargai perbedaan dan peduli pada rekan kerja, mitra, dan pemangku kepentingan.</td></tr><tr><td data-label="Nilai"><strong>Integrity</strong></td><td data-label="Artinya">Menjalankan usaha dengan jujur dan berpegang pada prinsip yang kuat.</td></tr><tr><td data-label="Nilai"><strong>Discipline</strong></td><td data-label="Artinya">Konsisten mematuhi aturan dan prosedur kerja.</td></tr><tr><td data-label="Nilai"><strong>Excellence</strong></td><td data-label="Artinya">Terus meningkatkan efektivitas, efisiensi, ketelitian, dan kualitas hasil kerja.</td></tr></tbody></table><h2 id="lingkungan-dan-kepedulian-sosial" tabindex="-1">Lingkungan dan kepedulian sosial <a class="header-anchor" href="#lingkungan-dan-kepedulian-sosial" aria-label="Permalink to &quot;Lingkungan dan kepedulian sosial&quot;">​</a></h2><p>Perusahaan berupaya menghemat energi dalam produksi, mengurangi emisi, mengelola limbah dengan prinsip <em>reduce, reuse, recycle</em>, serta memakai bahan baku secara efisien. Sejak 2024, perusahaan juga memasang panel surya atap bersama PT Helio Synar Energi.</p><p>Upaya ini mendapat pengakuan berupa <strong>PROPER Biru</strong> untuk periode 2022–2023, serta penghargaan CSR dari Pemerintah Provinsi Jawa Barat pada 2024 dan 2025. Program sosialnya antara lain beasiswa pelajar, santunan anak yatim, buka puasa bersama, penanaman pohon, khitanan massal, dan donor darah.</p><h2 id="apa-hubungannya-dengan-gudang-teknik" tabindex="-1">Apa hubungannya dengan Gudang Teknik? <a class="header-anchor" href="#apa-hubungannya-dengan-gudang-teknik" aria-label="Permalink to &quot;Apa hubungannya dengan Gudang Teknik?&quot;">​</a></h2><p>Pabrik pipa baja butuh mesin yang selalu siap jalan. Mesin perlu dirawat, dan perawatan butuh spare part, alat kerja, bahan habis pakai, serta APD. Semua barang itu disimpan dan disalurkan oleh <strong>Gudang Teknik</strong>.</p><p>Jadi, kesalahan kecil di gudang bisa berdampak besar. Contohnya salah ambil ukuran bearing, atau stok tercatat ada padahal kosong. Kalau itu terjadi, perbaikan mesin bisa tertunda dan produksi pipa ikut terganggu.</p><h2 id="alamat-perusahaan" tabindex="-1">Alamat perusahaan <a class="header-anchor" href="#alamat-perusahaan" aria-label="Permalink to &quot;Alamat perusahaan&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Kantor</th><th>Alamat dan telepon</th></tr></thead><tbody><tr><td data-label="Kantor">Kantor komersial</td><td data-label="Alamat dan telepon">Bakrie Tower Lantai 7, Rasuna Epicentrum, Jl. H.R. Rasuna Said, Jakarta Selatan 12940. Telp. +62 21 2994 1270</td></tr><tr><td data-label="Kantor">PT Bakrie Pipe Industries</td><td data-label="Alamat dan telepon">Jl. Raya Pejuang, Pejuang, Medan Satria, Kota Bekasi 17131. Telp. +62 21 8871 135</td></tr><tr><td data-label="Kantor">PT Southeast Asia Pipe Industries</td><td data-label="Alamat dan telepon">Jl. Lintas Pantai Timur, Bakau Kramat Desa Sumur, Kec. Ketapang, Bakauheni, Lampung Selatan 35592. Telp. +62 727 331234</td></tr></tbody></table>',37)])])}const c=n(p,[["render",u]]);export{P as __pageData,c as default};
